using System;using System.Data.SqlClient;using System.IO;
namespace Training.Manager{public partial class Announcement:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();private string Sender{get{return "MANAGER:"+Session["ManagerID"].ToString();}}protected void Page_Load(object s,EventArgs e){if(Session["ManagerID"]==null)Response.Redirect("~/Default.aspx");if(!IsPostBack)BindGrid();}protected void btnSend_Click(object s,EventArgs e){if(string.IsNullOrWhiteSpace(txtTitle.Text)||string.IsNullOrWhiteSpace(txtMessage.Text)){lblMessage.Text="Title and Message are required.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}string id=Guid.NewGuid().ToString("N").Substring(0,12).ToUpper();string path=Server.MapPath("~/Uploads/Announcements/");if(!Directory.Exists(path))Directory.CreateDirectory(path);if(fuPdf.HasFile){string ext=Path.GetExtension(fuPdf.FileName).ToLower();if(ext!=".pdf"){lblMessage.Text="Only PDF file is allowed.";lblMessage.ForeColor=System.Drawing.Color.Red;return;}fuPdf.SaveAs(Path.Combine(path,id+".pdf"));}obj.ExecuteSql("INSERT INTO Announcement(AnnouncementID,TrainerID,Title,Message,Audience,CreatedOn,IsActive) VALUES(@AnnouncementID,@TrainerID,@Title,@Message,'All',GETDATE(),1)",new SqlParameter[]{new SqlParameter("@AnnouncementID",id),new SqlParameter("@TrainerID",Sender),new SqlParameter("@Title",txtTitle.Text.Trim()),new SqlParameter("@Message",txtMessage.Text.Trim())});txtTitle.Text="";txtMessage.Text="";lblMessage.Text="Announcement published successfully.";lblMessage.ForeColor=System.Drawing.Color.Green;BindGrid();}private void BindGrid(){DataTable d=obj.GetDataTable("SELECT AnnouncementID,Title,Message,CreatedOn FROM Announcement WHERE TrainerID=@TrainerID AND IsActive=1 ORDER BY CreatedOn DESC",new SqlParameter[]{new SqlParameter("@TrainerID",Sender)});d.Columns.Add("HasPdf",typeof(bool));foreach(DataRow r in d.Rows)r["HasPdf"]=File.Exists(Server.MapPath("~/Uploads/Announcements/"+r["AnnouncementID"]+".pdf"));gvAnnouncements.DataSource=d;gvAnnouncements.DataBind();}}}